import 'package:camera/camera.dart';
import 'package:flutter/material.dart';

List<CameraDescription> cameras = [];

Future<void> main() async {
  // 1. Flutter 바인딩 초기화 보장
  WidgetsFlutterBinding.ensureInitialized();

  // 2. 사용 가능한 카메라 목록 가져오기
  try {
    cameras = await availableCameras();
  } on CameraException catch (e) {
    print('Error fetching cameras: ${e.code}\n${e.description}');
  }

  runApp(const CameraApp());
}

class CameraApp extends StatelessWidget {
  const CameraApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: CameraScreen(cameras: cameras),
    );
  }
}

class CameraScreen extends StatefulWidget {
  final List<CameraDescription> cameras;
  const CameraScreen({super.key, required this.cameras});

  @override
  State<CameraScreen> createState() => _CameraScreenState();
}

class _CameraScreenState extends State<CameraScreen>
    with WidgetsBindingObserver, TickerProviderStateMixin {
  CameraController? controller;
  // ... (다른 상태 변수 생략: XFile, videoController 등)

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    if (widget.cameras.isNotEmpty) {
      // 첫 번째 카메라 (보통 후면)로 초기화 시작
      _initializeCameraController(widget.cameras[0]);
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    controller?.dispose();
    super.dispose();
  }

  // 앱 라이프사이클 관리 (공식 예제 필수 패턴)
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    final CameraController? cameraController = controller;
    if (cameraController == null || !cameraController.value.isInitialized) {
      return;
    }
    if (state == AppLifecycleState.inactive) {
      cameraController.dispose(); // 비활성화 시 해제
    } else if (state == AppLifecycleState.resumed) {
      _initializeCameraController(cameraController.description); // 재개 시 다시 초기화
    }
  }

  Future<void> _initializeCameraController(CameraDescription cameraDescription) async {
    final cameraController = CameraController(
      cameraDescription,
      ResolutionPreset.high, // 고해상도 설정
      enableAudio: true,
      imageFormatGroup: ImageFormatGroup.jpeg,
    );

    controller = cameraController;

    // 컨트롤러 상태 변화 리스너
    cameraController.addListener(() {
      if (mounted) setState(() {});
      if (cameraController.value.hasError) {
        print('Camera error: ${cameraController.value.errorDescription}');
      }
    });

    try {
      await cameraController.initialize();
      // 줌 레벨, 노출 범위 등 고급 설정 값 가져오기 (생략 가능)
      // await cameraController.getMaxZoomLevel()... 
    } on CameraException catch (e) {
      print('Initialization Error: ${e.code}');
    }

    if (mounted) { setState(() {}); }
  }

  Widget _cameraPreviewWidget() {
    if (controller == null || !controller!.value.isInitialized) {
      return const Center(child: CircularProgressIndicator());
    }

    // 줌 및 초점 제어를 위한 Listener/GestureDetector 추가
    return Listener(
      onPointerDown: (_) => setState(() => _pointers++), // 줌 제어용 포인터 카운트
      onPointerUp: (_) => setState(() => _pointers--),
      child: CameraPreview(
        controller!,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onScaleStart: _handleScaleStart, // 줌 시작
          onScaleUpdate: _handleScaleUpdate, // 줌 업데이트
          onTapDown: (details) => onViewFinderTap(details, context.size!), // 탭 투 포커스
        ),
      ),
    );
  }

  // ... (onViewFinderTap, _handleScaleStart, _handleScaleUpdate 구현 생략)
}

Future<XFile?> takePicture() async {
  final CameraController? cameraController = controller;
  if (cameraController == null || !cameraController.value.isInitialized) {
    return null;
  }
  if (cameraController.value.isTakingPicture) {
    return null; // 이미 촬영 중
  }
  try {
    final XFile file = await cameraController.takePicture();
    return file;
  } on CameraException catch (e) {
    print('Picture Error: ${e.code}');
    return null;
  }
}

Future<void> startVideoRecording() async {
  final CameraController? cameraController = controller;
  if (cameraController == null || !cameraController.value.isInitialized) {
    return;
  }
  if (cameraController.value.isRecordingVideo) {
    return;
  }
  try {
    await cameraController.startVideoRecording();
    if (mounted) setState(() {});
  } on CameraException catch (e) {
    print('Video Start Error: ${e.code}');
    return;
  }
}

Future<XFile?> stopVideoRecording() async {
  final CameraController? cameraController = controller;
  if (cameraController == null || !cameraController.value.isRecordingVideo) {
    return null;
  }
  try {
    final XFile file = await cameraController.stopVideoRecording();
    if (mounted) setState(() {});
    return file;
  } on CameraException catch (e) {
    print('Video Stop Error: ${e.code}');
    return null;
  }
}

