      // setState를 통해 화면에 썸네일 표시
    }
  });
}

// 1. 줌 제어 (GestureDetector의 onScaleUpdate에서 호출)
Future<void> _handleScaleUpdate(ScaleUpdateDetails details) async {
  // _pointers는 Listener에서 관리되는 터치 개수
  if (controller == null || _pointers != 2) return;

  // _currentScale, _baseScale, _minAvailableZoom, _maxAvailableZoom 사용
  _currentScale = (_baseScale * details.scale).clamp(
    _minAvailableZoom,
    _maxAvailableZoom,
  );

  await controller!.setZoomLevel(_currentScale);
}

// 2. 탭 투 포커스 및 노출 (GestureDetector의 onTapDown에서 호출)
void onViewFinderTap(TapDownDetails details, Size constraints) {
  if (controller == null) return;

  // 탭 위치를 0.0 ~ 1.0 사이의 정규화된 좌표로 변환
  final offset = Offset(
    details.localPosition.dx / constraints.width,
    details.localPosition.dy / constraints.height,
  );

  // 초점 및 노출 포인트 설정
  controller!.setFocusPoint(offset);
  controller!.setExposurePoint(offset);
}

// 3. 플래시 모드 설정
Future<void> setFlashMode(FlashMode mode) async {
  if (controller == null) return;
  try {
    await controller!.setFlashMode(mode);
  } on CameraException catch (e) {
    print('Flash Mode Error: ${e.code}');
  }
}
